"""`.Tex NSFW`: generated by export_nodes.py from library.blend; kept by hand from then on."""

NAME = '.Tex NSFW'
KIND = 'ShaderNodeTree'


def build(lib):
    t = lib.new_group(NAME, KIND, props={})

    t.socket('OUTPUT', 'Nipple', 'NodeSocketColor', default_value=(0.0, 0.0, 0.0, 0.0))
    t.socket('OUTPUT', 'Nipple (alpha)', 'NodeSocketFloat', subtype='FACTOR', min_value=0.0, max_value=1.0)
    t.socket('OUTPUT', 'Genital', 'NodeSocketColor', default_value=(0.0, 0.0, 0.0, 0.0))
    t.socket('OUTPUT', 'Underhair', 'NodeSocketColor', default_value=(0.0, 0.0, 0.0, 0.0))

    t.node('NodeFrame', 'Frame', props={
        'location': (-318.63156, 41.42105),
        'width': 613.6842,
        'height': 289.1579,
        'label': 'Textures from the texture folder',
        'color': (0.604, 0.604, 0.604),
    })
    t.node('NodeGroupOutput', 'Group Output', props={
        'location': (358.20566, -6.519226),
    })
    t.node('ShaderNodeMath', 'Math', parent='Frame', props={
        'location': (444.3155, -90.91046),
        'hide': True,
    })
    t.node('ShaderNodeMix', 'Mix.006', parent='Frame', inputs={'Factor_Float': 0.0}, outputs={'Result_Color': (0.0, 0.0, 0.0, 0.0)}, props={
        'location': (442.9626, -50.18225),
        'hide': True,
        'data_type': 'RGBA',
        'blend_type': 'ADD',
    })
    t.node('ShaderNodeTexImage', '_ST.png', parent='Frame', outputs={'Color': (0.0, 0.0, 0.0, 0.0)}, props={
        'location': (29.434326, -235.16042),
        'width': 331.34845,
        'label': 'genital',
        'hide': True,
    })
    t.node('ShaderNodeTexImage', '_ot2.png', parent='Frame', outputs={'Color': (0.0, 0.0, 0.0, 0.0)}, props={
        'location': (29.434326, -169.09186),
        'width': 324.6792,
        'label': 'underhair',
        'hide': True,
        'extension': 'CLIP',
    })
    t.node('ShaderNodeTexImage', '_ot1.png', parent='Frame', outputs={'Color': (0.0, 0.0, 0.0, 0.0)}, props={
        'location': (67.55844, -44.378815),
        'width': 289.19666,
        'label': 'nipple right',
        'hide': True,
        'extension': 'CLIP',
    })
    t.node('ShaderNodeTexImage', '_ot1.pngleft', parent='Frame', outputs={'Color': (0.0, 0.0, 0.0, 0.0)}, props={
        'location': (69.451355, -100.10419),
        'width': 283.19653,
        'label': 'nipple left',
        'hide': True,
        'show_texture': True,
        'extension': 'CLIP',
    })
    t.node('ShaderNodeGroup', 'pos', props={
        'node_tree': lib.group('.NSFW positioning'),
        'location': (-635.83673, -64.473785),
        'width': 254.51434,
    })

    t.link('_ot1.png', 'Color', 'Mix.006', 'A_Color')
    t.link('_ot1.pngleft', 'Color', 'Mix.006', 'B_Color')
    t.link('Mix.006', 'Result_Color', 'Group Output', 'Nipple')
    t.link('_ST.png', 'Color', 'Group Output', 'Genital')
    t.link('_ot2.png', 'Color', 'Group Output', 'Underhair')
    t.link('pos', 'Right nipple', '_ot1.png', 'Vector')
    t.link('pos', 'Left nipple', '_ot1.pngleft', 'Vector')
    t.link('pos', 'Underhair', '_ot2.png', 'Vector')
    t.link('_ot1.png', 'Alpha', 'Math', 'Value')
    t.link('_ot1.pngleft', 'Alpha', 'Math', 'Value_001')
    t.link('Math', 'Value', 'Group Output', 'Nipple (alpha)')
    return t
